FUNCTION_BLOCK FB_Subsea_WaterInjectionPump
(*
========================================================================================================================
  CYBER-PHYSICAL SYSTEM ARCHITECTURAL SPECIFICATION & CONTROL THEORY FORMULATION
  PROJECT      : ULTRA-DEEPWATER SUBSEA RAW SEAWATER INJECTION STATION (3,000 m WATER DEPTH, 300 bar SEABED AMBIENT)
  EQUIPMENT    : 12-STAGE BARREL CASING CENTRIFUGAL INJECTION PUMP (API 610 / ISO 13709 TYPE BB5)
  ACTUATION    : 4,500 kW / 6.6 kV SUBSEA VARIABLE SPEED DRIVE (VSD) INDUCTION MOTOR WITH INTEGRAL BARRIER FLUID COMPENSATOR
  SAFETY CLASS : SIL-3 FUNCTIONAL SAFETY ENGINE / IEC 61508 / IEC 61511 / ISO 13628-6 SUBSEA PRODUCTION CONTROL SYSTEMS
  SPECIFICATION: IEC 61131-3 3RD EDITION / ISA-18.2 ALARM MANAGEMENT / NORSOK U-001 SUBSEA PRODUCTION APPARATUS
  AUTHOR       : PRINCIPAL AUTOMATION FELLOW & CYBER-PHYSICAL SYSTEMS CHAIR (LUMINA SWARM)
------------------------------------------------------------------------------------------------------------------------
  THEORETICAL FORMULATION & HYDRODYNAMIC EQUATIONS:
    1. MULTI-STAGE CENTRIFUGAL HEAD & POWER CHARACTERISTICS (AFFINITY LAW PARAMETRIZATION):
       The total dynamic developed pressure across the 12 impeller stages is governed by the modified Euler head:
           H_total(Q, N) = a0 * (N / N_nom)^2 - a1 * (N / N_nom) * Q - a2 * Q^2
       where:
           N     = shaft rotational speed [rpm] (nominal N_nom = 4,800 rpm)
           Q     = raw seawater volumetric throughput [m3/h] (best efficiency point Q_BEP = 650 m3/h)
           a0    = 520.0 bar (shutoff zero-flow head at rated speed)
           a1    = 0.092 bar/(m3/h) (linear slip loss coefficient)
           a2    = 0.00018 bar/(m3/h)^2 (quadratic friction / turbulence loss coefficient)

    2. CAVITATION INCEPTION & ACOUSTIC SHOCK SUPPRESSION:
       Cavitation occurs when the static absolute pressure in the first-stage impeller suction eye drops below the
       local vapor pressure (P_vapor(T_sw) = 0.012 bar abs at 4.0 deg C seawater).
       Available Net Positive Suction Head (NPSH_A) in meters of liquid column:
           NPSH_A = ((P_suction - P_vapor) * 1.0E5) / (rho_sw * g_local) + (v_suction^2) / (2.0 * g_local)
       Required Net Positive Suction Head (NPSH_R):
           NPSH_R = c0 * (N / N_nom)^2 + c1 * (Q / Q_nom)^2
       To prevent destructive high-frequency micro-jet pitting and rotor vibration breakdown:
           NPSH_Margin = NPSH_A - NPSH_R >= Margin_Threshold (typically >= 15.0 m liquid column)
       Continuous Minimum Flow (Q_min_cont) is dynamically enforced via the fast-acting anti-cavitation kickback choke:
           Q_min_cont(N) = Q_min_base * (N / N_nom)^1.15

    3. STATE-SPACE DISCRETE MODEL PREDICTIVE CONTROL (MPC):
       Linearized discrete plant dynamics (Sampling period Ts = 100 ms):
           x(k+1) = A * x(k) + B * u(k) + E * d(k)
           y(k)   = C * x(k) + D * u(k)
       State Vector:
           x_1 = Delta_Q        (Volumetric flow deviation from setpoint [m3/h])
           x_2 = Delta_P_disch  (Discharge manifold pressure deviation [bar])
           x_3 = Delta_N        (Shaft rotational speed deviation [rpm])
           x_4 = Delta_P_barr   (Motor dielectric barrier fluid overpressure deviation [bar])
       Manipulated Variables:
           u_1 = Delta_N_cmd    (VSD speed setpoint rate command [rpm])
           u_2 = Delta_u_kick   (Anti-cavitation kickback recirculation choke valve opening [%])
       Unmeasured / Feedforward Disturbance:
           d_1 = Delta_P_wellhead (Reservoir pore pressure backpressure variation [bar])

    4. TRIPLE MODULAR REDUNDANCY (2oo3 TMR) SENSOR VOTING ARCHITECTURE:
       Both Subsea Suction Pressure (PT) and Subsea Discharge Flow (FT) are measured via dual-redundant 2oo3 TMR arrays.
       Voting logic executes:
           a. Sensor plausibility bounds check [0.0 .. 350.0 bar] and [0.0 .. 1200.0 m3/h].
           b. Cross-channel difference computation (Delta_12, Delta_23, Delta_31).
           c. Automatic median / mean resolution with single-sensor drift exclusion.
           d. Seamless degradation sequence: 2oo3 -> 2oo2 -> 1oo1 -> Failsafe Kickback Open.
========================================================================================================================
*)

VAR_INPUT
    (* --- Master Permissives & Safety Interlocks --- *)
    bMasterPermissive           : BOOL;     (* Subsea topside injection master permissive [TRUE=Run Permitted] *)
    bSubseaESD_Trip             : BOOL;     (* Subsea hardwired Emergency Shutdown loop [FALSE=Healthy, TRUE=Tripped] *)
    bAutoMpcEnable              : BOOL;     (* Supervisory closed-loop state-space MPC active command *)
    bAcknowledgeFaults          : BOOL;     (* Operator fault reset and diagnostic latch clear command *)

    (* --- Subsea 2oo3 Triple Modular Pressure & Flow Instrumentation --- *)
    rSuctionPress_PT1_bar       : REAL;     (* Redundant subsea suction pressure transmitter 1 [bar] (0.0 .. 350.0) *)
    rSuctionPress_PT2_bar       : REAL;     (* Redundant subsea suction pressure transmitter 2 [bar] (0.0 .. 350.0) *)
    rSuctionPress_PT3_bar       : REAL;     (* Redundant subsea suction pressure transmitter 3 [bar] (0.0 .. 350.0) *)
    rDischargePress_bar         : REAL;     (* Subsea discharge manifold multi-stage pressure transmitter [bar] (0.0 .. 700.0) *)
    rDischargeFlow_FT1_m3h      : REAL;     (* Redundant subsea venturi injection flow transmitter 1 [m3/h] (0.0 .. 1200.0) *)
    rDischargeFlow_FT2_m3h      : REAL;     (* Redundant subsea venturi injection flow transmitter 2 [m3/h] (0.0 .. 1200.0) *)
    rDischargeFlow_FT3_m3h      : REAL;     (* Redundant subsea venturi injection flow transmitter 3 [m3/h] (0.0 .. 1200.0) *)

    (* --- Electro-Mechanical Drives, Rotor Dynamics & Thermal Telemetry --- *)
    rPumpSpeed_Feedback_rpm     : REAL;     (* Subsea VSD motor resolver shaft speed feedback [rpm] (0.0 .. 6500.0) *)
    rMotorActivePower_kW        : REAL;     (* Subsea electric canned motor active power feedback [kW] (0.0 .. 5000.0) *)
    rSeawaterInletTemp_DegC     : REAL;     (* Seabed ambient raw seawater suction temperature [deg C] (-2.0 .. 35.0) *)
    rMotorWindingTemp_DegC      : REAL;     (* VSD stator RTD maximum winding core temperature [deg C] (0.0 .. 180.0) *)
    rThrustBearingTemp_DegC     : REAL;     (* Multi-pad hydrodynamic thrust bearing metal temp [deg C] (0.0 .. 150.0) *)
    rBarrierFluidDeltaP_bar     : REAL;     (* Motor dielectric fluid overpressure relative to seawater [bar] (1.0 .. 15.0) *)
    rWellheadBackpress_bar      : REAL;     (* Downhole geological formation reservoir backpressure [bar] (0.0 .. 600.0) *)

    (* --- Operational Target References --- *)
    rTargetInjectionFlow_m3h    : REAL;     (* Reservoir engineer target injection volumetric flow [m3/h] *)
    rTargetDischargePress_bar   : REAL;     (* Reservoir engineer target manifold discharge pressure [bar] *)
END_VAR

VAR_OUTPUT
    (* --- Primary Actuation Commands & Setpoints --- *)
    bPumpSystemReady            : BOOL;     (* Subsea water injection station operational readiness status *)
    bDegradedModeActive         : BOOL;     (* Operating under sensor failure or thermal de-rated condition *)
    bAntiCavitationActive       : BOOL;     (* Minimum flow bypass kickback choke actively overriding *)
    rVsdSpeedSetpoint_rpm       : REAL;     (* Subsea variable speed drive rotational velocity demand [rpm] (0.0 .. 6000.0) *)
    rMinFlowValve_Cmd_Pct       : REAL;     (* Anti-cavitation recirculation choke valve opening command [%] (0.0 .. 100.0) *)

    (* --- Validated Process Telemetry & Diagnostics --- *)
    rVotedSuctionPress_bar      : REAL;     (* 2oo3 TMR validated subsea suction pressure [bar] *)
    rVotedDischargeFlow_m3h     : REAL;     (* 2oo3 TMR validated subsea raw seawater flow rate [m3/h] *)
    rInjectionDischargePress_bar: REAL;     (* Filtered validated injection discharge manifold pressure [bar] *)
    rNetPositiveSuctionHeadMargin_m: REAL;  (* Calculated subsea cavitation margin NPSH_A - NPSH_R [m] *)
    rPumpHydraulicPower_kW      : REAL;     (* Calculated instantaneous hydraulic fluid power delivered [kW] *)
    rPumpEfficiency_Pct         : REAL;     (* Real-time wire-to-water overall pump hydraulic efficiency [%] *)

    (* --- Status & ISA-18.2 Alarm Registers --- *)
    wSubseaAlarmWord            : WORD;     (* ISA-18.2 packed alarm register (Bit0=ESD, Bit1=Cavitation, etc.) *)
    wPumpStatusWord             : WORD;     (* Subsea pump finite state machine and health status word *)
END_VAR

VAR
    (* --- State Machine Control & Sequencing --- *)
    iState                      : INT := 0; (* Operational finite state machine index *)
    iPreviousState              : INT := 0; (* Previous state tracker for bumpless transition *)

    (* --- Triple Modular Redundancy (2oo3) Voting: Suction Pressure (PT) --- *)
    bPT1_Valid                  : BOOL := TRUE;
    bPT2_Valid                  : BOOL := TRUE;
    bPT3_Valid                  : BOOL := TRUE;
    iHealthy_PT_Count           : INT  := 3;
    rDeltaPT12                  : REAL := 0.0;
    rDeltaPT23                  : REAL := 0.0;
    rDeltaPT31                  : REAL := 0.0;
    rPT_TmrTolerance_bar        : REAL := 4.5; (* Permissible inter-transmitter variance limit [bar] *)

    (* --- Triple Modular Redundancy (2oo3) Voting: Discharge Flow (FT) --- *)
    bFT1_Valid                  : BOOL := TRUE;
    bFT2_Valid                  : BOOL := TRUE;
    bFT3_Valid                  : BOOL := TRUE;
    iHealthy_FT_Count           : INT  := 3;
    rDeltaFT12                  : REAL := 0.0;
    rDeltaFT23                  : REAL := 0.0;
    rDeltaFT31                  : REAL := 0.0;
    rFT_TmrTolerance_m3h        : REAL := 25.0; (* Permissible venturi meter variance limit [m3/h] *)

    (* --- State-Space Discrete Model Representation (Ts = 0.1 s) --- *)
    (* State Vector:
         x1 = Delta_Q (Flow deviation from setpoint [m3/h])
         x2 = Delta_P (Discharge pressure deviation from setpoint [bar])
         x3 = Delta_N (Rotor speed deviation from setpoint [rpm])
         x4 = Delta_P_barrier (Barrier fluid overpressure deviation from 3.5 bar [bar])
    *)
    rState_x1_FlowErr           : REAL := 0.0;
    rState_x2_PressErr          : REAL := 0.0;
    rState_x3_SpeedErr          : REAL := 0.0;
    rState_x4_BarrierErr        : REAL := 0.0;

    (* Linearized Plant Transition Matrix A (4x4) *)
    rA11 : REAL := 0.9120;  rA12 : REAL := -0.0480; rA13 : REAL := 0.1420;  rA14 : REAL := 0.0000;
    rA21 : REAL := 0.0850;  rA22 : REAL := 0.8950;  rA23 : REAL := 0.2280;  rA24 : REAL := 0.0000;
    rA31 : REAL := -0.0120; rA32 : REAL := -0.0085; rA33 : REAL := 0.9550;  rA34 : REAL := 0.0000;
    rA41 : REAL := 0.0000;  rA42 : REAL := 0.0000;  rA43 : REAL := 0.0012;  rA44 : REAL := 0.9820;

    (* Linearized Input Coupling Matrix B (4x2) *)
    rB11 : REAL := 0.1380;  rB12 : REAL := -0.4200; (* u1=Speed command, u2=Kickback valve *)
    rB21 : REAL := 0.2450;  rB22 : REAL := -0.1850;
    rB31 : REAL := 0.7200;  rB32 : REAL := 0.0000;
    rB41 : REAL := 0.0025;  rB42 : REAL := 0.0000;

    (* MPC Cost Function Weighting Factors & Prediction Horizons *)
    rWeight_FlowErr             : REAL := 1.25;
    rWeight_PressErr            : REAL := 2.80;
    rWeight_CavitationPenalty   : REAL := 15.0;
    rWeight_ActuatorEffort      : REAL := 0.45;
    rPredFlow_Step1             : REAL := 0.0;
    rPredPress_Step1            : REAL := 0.0;

    (* Anti-Cavitation & Hydrodynamic Calculations *)
    rNPSH_Available             : REAL := 0.0;
    rNPSH_Required              : REAL := 0.0;
    rContinuousMinFlow_m3h      : REAL := 320.0; (* Base continuous minimum flow [m3/h] at rated speed *)
    rDynamicMinFlow_Threshold   : REAL := 320.0;
    rSeawaterDensity_kgm3       : REAL := 1032.0; (* Ultra-deep cold raw seawater density [kg/m3] *)
    rGravity_ms2                : REAL := 9.81;

    (* Digital Low-Pass Filtering Accumulators (First Order EMA) *)
    rFilt_SuctionPress_bar      : REAL := 0.0;
    rFilt_DischargePress_bar    : REAL := 0.0;
    rFilt_DischargeFlow_m3h     : REAL := 0.0;
    rFilt_Speed_rpm             : REAL := 0.0;
    rFilt_Power_kW              : REAL := 0.0;
    rFilt_WindingTemp_DegC      : REAL := 0.0;
    rFilt_BearingTemp_DegC      : REAL := 0.0;

    (* Safety Timers & Critical Stage Sequencing *)
    tonSeabedPrecheck           : TON;
    tonSlowRollWarmup           : TON;
    tonRampRateLimiter          : TON;
    tonCavitationPersistence    : TON;
    tonTripDebounce             : TON;
    tonDegradedWatchdog         : TON;

    (* System Diagnostics, Metrics & Counters *)
    udiCycleCounter             : UDINT := 0;
    udiCavitationEventsTotal    : UDINT := 0;
    rCumulativeInjected_m3      : LREAL := 0.0;
    rInternalSpeedDemand_rpm    : REAL := 0.0;
    rInternalKickback_Cmd_Pct   : REAL := 100.0; (* Default fail-safe 100% open *)
END_VAR

(*
========================================================================================================================
  MAIN CYCLIC LOGIC IMPLEMENTATION (EXECUTION FREQUENCY: 10 Hz / 100 ms)
========================================================================================================================
*)

udiCycleCounter := udiCycleCounter + 1;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 1: CRITICAL SUBSEA SAFETY INTERLOCKS & SIL-3 EMERGENCY SHUTDOWN (ESD)
   --------------------------------------------------------------------------------------------------------------------- *)
IF bSubseaESD_Trip OR (NOT bMasterPermissive) THEN
    (* Instantaneous Deterministic Fail-Safe Actuation *)
    bPumpSystemReady            := FALSE;
    bDegradedModeActive         := FALSE;
    bAntiCavitationActive       := TRUE;
    rVsdSpeedSetpoint_rpm       := 0.0;
    rInternalSpeedDemand_rpm    := 0.0;
    rMinFlowValve_Cmd_Pct       := 100.0; (* Fully open anti-cavitation kickback choke to depressurize *)
    rInternalKickback_Cmd_Pct   := 100.0;

    wSubseaAlarmWord.0          := bSubseaESD_Trip; (* ESD Trip Active *)
    wSubseaAlarmWord.1          := NOT bMasterPermissive; (* Master Permissive Missing *)
    wPumpStatusWord             := 16#F000;
    iState                      := 99; (* Transition directly to emergency shutdown state *)
    RETURN;
END_IF;

wSubseaAlarmWord.0 := FALSE;
wSubseaAlarmWord.1 := FALSE;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 2: DUAL 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) SENSOR VOTING ENGINES
   --------------------------------------------------------------------------------------------------------------------- *)
(* --- ENGINE A: Subsea Suction Pressure 2oo3 Voting --- *)
bPT1_Valid := (rSuctionPress_PT1_bar >= 5.0) AND (rSuctionPress_PT1_bar <= 350.0);
bPT2_Valid := (rSuctionPress_PT2_bar >= 5.0) AND (rSuctionPress_PT2_bar <= 350.0);
bPT3_Valid := (rSuctionPress_PT3_bar >= 5.0) AND (rSuctionPress_PT3_bar <= 350.0);

rDeltaPT12 := ABS(rSuctionPress_PT1_bar - rSuctionPress_PT2_bar);
rDeltaPT23 := ABS(rSuctionPress_PT2_bar - rSuctionPress_PT3_bar);
rDeltaPT31 := ABS(rSuctionPress_PT3_bar - rSuctionPress_PT1_bar);

IF bPT1_Valid AND bPT2_Valid AND bPT3_Valid THEN
    IF (rDeltaPT12 <= rPT_TmrTolerance_bar) AND (rDeltaPT23 <= rPT_TmrTolerance_bar) AND (rDeltaPT31 <= rPT_TmrTolerance_bar) THEN
        rVotedSuctionPress_bar := (rSuctionPress_PT1_bar + rSuctionPress_PT2_bar + rSuctionPress_PT3_bar) / 3.0;
        iHealthy_PT_Count      := 3;
        wSubseaAlarmWord.2     := FALSE; (* PT TMR healthy *)
    ELSIF (rDeltaPT12 <= rPT_TmrTolerance_bar) THEN
        rVotedSuctionPress_bar := (rSuctionPress_PT1_bar + rSuctionPress_PT2_bar) / 2.0;
        bPT3_Valid             := FALSE;
        iHealthy_PT_Count      := 2;
        wSubseaAlarmWord.2     := TRUE;  (* PT3 sensor drift *)
    ELSIF (rDelta23 <= rPT_TmrTolerance_bar) THEN
        rVotedSuctionPress_bar := (rSuctionPress_PT2_bar + rSuctionPress_PT3_bar) / 2.0;
        bPT1_Valid             := FALSE;
        iHealthy_PT_Count      := 2;
        wSubseaAlarmWord.2     := TRUE;  (* PT1 sensor drift *)
    ELSIF (rDeltaPT31 <= rPT_TmrTolerance_bar) THEN
        rVotedSuctionPress_bar := (rSuctionPress_PT1_bar + rSuctionPress_PT3_bar) / 2.0;
        bPT2_Valid             := FALSE;
        iHealthy_PT_Count      := 2;
        wSubseaAlarmWord.2     := TRUE;  (* PT2 sensor drift *)
    ELSE
        (* Total Suction Pressure Discrepancy - Take conservative minimum to preserve cavitation safety *)
        rVotedSuctionPress_bar := MIN(rSuctionPress_PT1_bar, MIN(rSuctionPress_PT2_bar, rSuctionPress_PT3_bar));
        iHealthy_PT_Count      := 1;
        wSubseaAlarmWord.2     := TRUE;
        wSubseaAlarmWord.3     := TRUE;  (* Severe PT inconsistency *)
    END_IF;
ELSIF bPT1_Valid AND bPT2_Valid THEN
    rVotedSuctionPress_bar := (rSuctionPress_PT1_bar + rSuctionPress_PT2_bar) / 2.0;
    iHealthy_PT_Count      := 2;
    wSubseaAlarmWord.2     := TRUE;
ELSIF bPT2_Valid AND bPT3_Valid THEN
    rVotedSuctionPress_bar := (rSuctionPress_PT2_bar + rSuctionPress_PT3_bar) / 2.0;
    iHealthy_PT_Count      := 2;
    wSubseaAlarmWord.2     := TRUE;
ELSIF bPT1_Valid AND bPT3_Valid THEN
    rVotedSuctionPress_bar := (rSuctionPress_PT1_bar + rSuctionPress_PT3_bar) / 2.0;
    iHealthy_PT_Count      := 2;
    wSubseaAlarmWord.2     := TRUE;
ELSIF bPT1_Valid THEN
    rVotedSuctionPress_bar := rSuctionPress_PT1_bar;
    iHealthy_PT_Count      := 1;
    wSubseaAlarmWord.3     := TRUE;
ELSIF bPT2_Valid THEN
    rVotedSuctionPress_bar := rSuctionPress_PT2_bar;
    iHealthy_PT_Count      := 1;
    wSubseaAlarmWord.3     := TRUE;
ELSIF bPT3_Valid THEN
    rVotedSuctionPress_bar := rSuctionPress_PT3_bar;
    iHealthy_PT_Count      := 1;
    wSubseaAlarmWord.3     := TRUE;
ELSE
    rVotedSuctionPress_bar := 10.0; (* Fallback baseline seabed hydrostatic assumption *)
    iHealthy_PT_Count      := 0;
    wSubseaAlarmWord.3     := TRUE;
END_IF;

(* --- ENGINE B: Subsea Discharge Flow 2oo3 Voting --- *)
bFT1_Valid := (rDischargeFlow_FT1_m3h >= 0.0) AND (rDischargeFlow_FT1_m3h <= 1200.0);
bFT2_Valid := (rDischargeFlow_FT2_m3h >= 0.0) AND (rDischargeFlow_FT2_m3h <= 1200.0);
bFT3_Valid := (rDischargeFlow_FT3_m3h >= 0.0) AND (rDischargeFlow_FT3_m3h <= 1200.0);

rDeltaFT12 := ABS(rDischargeFlow_FT1_m3h - rDischargeFlow_FT2_m3h);
rDeltaFT23 := ABS(rDischargeFlow_FT2_m3h - rDischargeFlow_FT3_m3h);
rDeltaFT31 := ABS(rDischargeFlow_FT3_m3h - rDischargeFlow_FT1_m3h);

IF bFT1_Valid AND bFT2_Valid AND bFT3_Valid THEN
    IF (rDeltaFT12 <= rFT_TmrTolerance_m3h) AND (rDeltaFT23 <= rFT_TmrTolerance_m3h) AND (rDeltaFT31 <= rFT_TmrTolerance_m3h) THEN
        rVotedDischargeFlow_m3h := (rDischargeFlow_FT1_m3h + rDischargeFlow_FT2_m3h + rDischargeFlow_FT3_m3h) / 3.0;
        iHealthy_FT_Count       := 3;
        wSubseaAlarmWord.4      := FALSE; (* FT TMR healthy *)
    ELSIF (rDeltaFT12 <= rFT_TmrTolerance_m3h) THEN
        rVotedDischargeFlow_m3h := (rDischargeFlow_FT1_m3h + rDischargeFlow_FT2_m3h) / 2.0;
        bFT3_Valid              := FALSE;
        iHealthy_FT_Count       := 2;
        wSubseaAlarmWord.4      := TRUE;  (* FT3 sensor divergence *)
    ELSIF (rDeltaFT23 <= rFT_TmrTolerance_m3h) THEN
        rVotedDischargeFlow_m3h := (rDischargeFlow_FT2_m3h + rDischargeFlow_FT3_m3h) / 2.0;
        bFT1_Valid              := FALSE;
        iHealthy_FT_Count       := 2;
        wSubseaAlarmWord.4      := TRUE;  (* FT1 sensor divergence *)
    ELSIF (rDeltaFT31 <= rFT_TmrTolerance_m3h) THEN
        rVotedDischargeFlow_m3h := (rDischargeFlow_FT1_m3h + rDischargeFlow_FT3_m3h) / 2.0;
        bFT2_Valid              := FALSE;
        iHealthy_FT_Count       := 2;
        wSubseaAlarmWord.4      := TRUE;  (* FT2 sensor divergence *)
    ELSE
        (* Total Flow Variance: Take median of three signals *)
        IF ((rDischargeFlow_FT1_m3h >= rDischargeFlow_FT2_m3h) AND (rDischargeFlow_FT1_m3h <= rDischargeFlow_FT3_m3h)) OR
           ((rDischargeFlow_FT1_m3h <= rDischargeFlow_FT2_m3h) AND (rDischargeFlow_FT1_m3h >= rDischargeFlow_FT3_m3h)) THEN
            rVotedDischargeFlow_m3h := rDischargeFlow_FT1_m3h;
        ELSIF ((rDischargeFlow_FT2_m3h >= rDischargeFlow_FT1_m3h) AND (rDischargeFlow_FT2_m3h <= rDischargeFlow_FT3_m3h)) OR
              ((rDischargeFlow_FT2_m3h <= rDischargeFlow_FT1_m3h) AND (rDischargeFlow_FT2_m3h >= rDischargeFlow_FT3_m3h)) THEN
            rVotedDischargeFlow_m3h := rDischargeFlow_FT2_m3h;
        ELSE
            rVotedDischargeFlow_m3h := rDischargeFlow_FT3_m3h;
        END_IF;
        iHealthy_FT_Count  := 1;
        wSubseaAlarmWord.4 := TRUE;
        wSubseaAlarmWord.5 := TRUE; (* Severe FT disagreement *)
    END_IF;
ELSIF bFT1_Valid AND bFT2_Valid THEN
    rVotedDischargeFlow_m3h := (rDischargeFlow_FT1_m3h + rDischargeFlow_FT2_m3h) / 2.0;
    iHealthy_FT_Count       := 2;
    wSubseaAlarmWord.4      := TRUE;
ELSIF bFT2_Valid AND bFT3_Valid THEN
    rVotedDischargeFlow_m3h := (rDischargeFlow_FT2_m3h + rDischargeFlow_FT3_m3h) / 2.0;
    iHealthy_FT_Count       := 2;
    wSubseaAlarmWord.4      := TRUE;
ELSIF bFT1_Valid AND bFT3_Valid THEN
    rVotedDischargeFlow_m3h := (rDischargeFlow_FT1_m3h + rDischargeFlow_FT3_m3h) / 2.0;
    iHealthy_FT_Count       := 2;
    wSubseaAlarmWord.4      := TRUE;
ELSIF bFT1_Valid THEN
    rVotedDischargeFlow_m3h := rDischargeFlow_FT1_m3h;
    iHealthy_FT_Count       := 1;
    wSubseaAlarmWord.5      := TRUE;
ELSIF bFT2_Valid THEN
    rVotedDischargeFlow_m3h := rDischargeFlow_FT2_m3h;
    iHealthy_FT_Count       := 1;
    wSubseaAlarmWord.5      := TRUE;
ELSIF bFT3_Valid THEN
    rVotedDischargeFlow_m3h := rDischargeFlow_FT3_m3h;
    iHealthy_FT_Count       := 1;
    wSubseaAlarmWord.5      := TRUE;
ELSE
    rVotedDischargeFlow_m3h := 0.0;
    iHealthy_FT_Count       := 0;
    wSubseaAlarmWord.5      := TRUE;
END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 3: DIGITAL FILTERING & CYBER-PHYSICAL HYDRODYNAMIC PARAMETER ESTIMATION
   --------------------------------------------------------------------------------------------------------------------- *)
(* First-order low-pass exponential moving average (EMA) filters for continuous stabilization *)
rFilt_SuctionPress_bar   := (rFilt_SuctionPress_bar * 0.80) + (rVotedSuctionPress_bar * 0.20);
rFilt_DischargePress_bar := (rFilt_DischargePress_bar * 0.85) + (rDischargePress_bar * 0.15);
rFilt_DischargeFlow_m3h  := (rFilt_DischargeFlow_m3h * 0.75) + (rVotedDischargeFlow_m3h * 0.25);
rFilt_Speed_rpm          := (rFilt_Speed_rpm * 0.70) + (rPumpSpeed_Feedback_rpm * 0.30);
rFilt_Power_kW           := (rFilt_Power_kW * 0.80) + (rMotorActivePower_kW * 0.20);
rFilt_WindingTemp_DegC   := (rFilt_WindingTemp_DegC * 0.95) + (rMotorWindingTemp_DegC * 0.05);
rFilt_BearingTemp_DegC   := (rFilt_BearingTemp_DegC * 0.95) + (rThrustBearingTemp_DegC * 0.05);

rInjectionDischargePress_bar := rFilt_DischargePress_bar;

(* Calculate Hydraulic Output Power [kW]: P_hyd = (Q [m3/h] * Delta_P [bar] * 100) / 3600 *)
IF rFilt_DischargePress_bar > rFilt_SuctionPress_bar THEN
    rPumpHydraulicPower_kW := (rFilt_DischargeFlow_m3h * (rFilt_DischargePress_bar - rFilt_SuctionPress_bar) * 100.0) / 3600.0;
ELSE
    rPumpHydraulicPower_kW := 0.0;
END_IF;

(* Wire-to-water overall pump hydraulic efficiency [%] *)
IF rFilt_Power_kW > 50.0 THEN
    rPumpEfficiency_Pct := (rPumpHydraulicPower_kW / rFilt_Power_kW) * 100.0;
    IF rPumpEfficiency_Pct > 92.0 THEN
        rPumpEfficiency_Pct := 92.0; (* Thermodynamic maximum limit *)
    ELSIF rPumpEfficiency_Pct < 0.0 THEN
        rPumpEfficiency_Pct := 0.0;
    END_IF;
ELSE
    rPumpEfficiency_Pct := 0.0;
END_IF;

(* Real-Time Cavitation Margin Calculation: NPSH_A vs NPSH_R *)
(* Suction static head [m liquid]: P * 1e5 / (rho * g) *)
rNPSH_Available := ((rFilt_SuctionPress_bar - 0.015) * 100000.0) / (rSeawaterDensity_kgm3 * rGravity_ms2);

(* Required NPSH calculated dynamically via Affinity Law quadratic scaling *)
rNPSH_Required := (8.5 * EXPT((rFilt_Speed_rpm / 4800.0), 2.0)) + 
                  (6.2 * EXPT((rFilt_DischargeFlow_m3h / 650.0), 2.0));

rNetPositiveSuctionHeadMargin_m := rNPSH_Available - rNPSH_Required;

(* Dynamic Minimum Flow Limit scaling with shaft rotational velocity *)
rDynamicMinFlow_Threshold := rContinuousMinFlow_m3h * EXPT((MAX(rFilt_Speed_rpm, 1200.0) / 4800.0), 1.15);

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 4: STATE-SPACE DISCRETE MODEL PREDICTIVE CONTROL (MPC) RECURSION
   --------------------------------------------------------------------------------------------------------------------- *)
(* Error coordinates relative to engineering setpoints *)
rState_x1_FlowErr    := rTargetInjectionFlow_m3h - rFilt_DischargeFlow_m3h;
rState_x2_PressErr   := rTargetDischargePress_bar - rFilt_DischargePress_bar;
rState_x3_SpeedErr   := rInternalSpeedDemand_rpm - rFilt_Speed_rpm;
rState_x4_BarrierErr := 3.50 - rBarrierFluidDeltaP_bar; (* Nominal 3.5 bar differential *)

(* One-Step Ahead State Prediction: x(k+1) = A*x(k) + B*u(k) *)
rPredFlow_Step1 := (rA11 * rState_x1_FlowErr) + (rA12 * rState_x2_PressErr) + (rA13 * rState_x3_SpeedErr) +
                   (rB11 * (rInternalSpeedDemand_rpm - 4800.0) * 0.01) + (rB12 * (rInternalKickback_Cmd_Pct * 0.01));

rPredPress_Step1 := (rA21 * rState_x1_FlowErr) + (rA22 * rState_x2_PressErr) + (rA23 * rState_x3_SpeedErr) +
                    (rB21 * (rInternalSpeedDemand_rpm - 4800.0) * 0.01) + (rB22 * (rInternalKickback_Cmd_Pct * 0.01));

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 5: FINITE STATE MACHINE SEQUENCING (ISA-88 SUBSEA STATES)
   --------------------------------------------------------------------------------------------------------------------- *)
CASE iState OF

    0: (* STATE_INIT_SEABED_DIAGNOSTICS: Integrity verification at 3,000 m seabed depth *)
        bPumpSystemReady         := FALSE;
        bDegradedModeActive      := FALSE;
        bAntiCavitationActive    := TRUE;
        rInternalSpeedDemand_rpm := 0.0;
        rInternalKickback_Cmd_Pct:= 100.0; (* Kickback choke 100% open to relieve startup pressure *)
        wPumpStatusWord          := 16#0001;

        (* Verify Barrier Fluid Overpressure and Seabed Instruments *)
        tonSeabedPrecheck(IN := (rBarrierFluidDeltaP_bar >= 2.0) AND (iHealthy_PT_Count >= 2) AND (iHealthy_FT_Count >= 2),
                          PT := T#15S);

        IF tonSeabedPrecheck.Q THEN
            tonSeabedPrecheck(IN := FALSE);
            iState := 10; (* Transition to Barrier Purge & Slow Roll *)
        ELSIF rBarrierFluidDeltaP_bar < 1.5 THEN
            wSubseaAlarmWord.6 := TRUE; (* Barrier fluid loss alarm *)
        END_IF;

    10: (* STATE_BARRIER_PURGE_SLOW_ROLL: 600 rpm hydrodynamic bearing film formation *)
        bPumpSystemReady         := FALSE;
        bDegradedModeActive      := FALSE;
        bAntiCavitationActive    := TRUE;
        rInternalSpeedDemand_rpm := 600.0; (* Minimum shaft speed for tilt-pad oil wedging *)
        rInternalKickback_Cmd_Pct:= 100.0;
        wPumpStatusWord          := 16#0010;

        tonSlowRollWarmup(IN := (rFilt_Speed_rpm >= 550.0) AND (rFilt_Speed_rpm <= 650.0), PT := T#45S);

        IF tonSlowRollWarmup.Q THEN
            tonSlowRollWarmup(IN := FALSE);
            IF bAutoMpcEnable THEN
                iState := 20; (* Proceed to Critical Resonance Acceleration Ramp *)
            END_IF;
        END_IF;

    20: (* STATE_CRITICAL_SPEED_RAMP_ACCELERATION: Rapid jump past rotor resonance (1200-1450 rpm) *)
        bPumpSystemReady         := TRUE;
        bDegradedModeActive      := FALSE;
        bAntiCavitationActive    := TRUE;
        wPumpStatusWord          := 16#0020;
        rInternalKickback_Cmd_Pct:= 100.0; (* Maintain full bypass to avoid stall *)

        (* S-curve acceleration profile towards baseline minimum operating speed of 3,600 rpm *)
        IF rInternalSpeedDemand_rpm < 3600.0 THEN
            rInternalSpeedDemand_rpm := rInternalSpeedDemand_rpm + 50.0; (* 500 rpm/s equivalent rate *)
        ELSE
            rInternalSpeedDemand_rpm := 3600.0;
            iState                   := 30; (* Advance to Steady-State Closed-Loop Injection *)
        END_IF;

    30: (* STATE_STEADY_STATE_MPC_INJECTION: Optimal Dual-Loop Closed-Loop Pressure & Flow Control *)
        bPumpSystemReady         := TRUE;
        bDegradedModeActive      := (iHealthy_PT_Count < 3) OR (iHealthy_FT_Count < 3) OR (rFilt_WindingTemp_DegC > 130.0);
        wPumpStatusWord          := 16#0030;

        (* Sub-Loop 1: Model Predictive VSD Speed Command Formulation *)
        IF bAutoMpcEnable THEN
            rInternalSpeedDemand_rpm := rInternalSpeedDemand_rpm + 
                                       (rPredFlow_Step1 * rWeight_FlowErr * 0.12) +
                                       (rPredPress_Step1 * rWeight_PressErr * 0.25);
            (* Mechanical envelope hard limits *)
            IF rInternalSpeedDemand_rpm > 5400.0 THEN
                rInternalSpeedDemand_rpm := 5400.0; (* VSD maximum overspeed cap *)
            ELSIF rInternalSpeedDemand_rpm < 3200.0 THEN
                rInternalSpeedDemand_rpm := 3200.0; (* Minimum continuous operational speed *)
            END_IF;
        END_IF;

        (* Sub-Loop 2: Anti-Cavitation Kickback Choke Modulation *)
        IF rFilt_DischargeFlow_m3h < (rDynamicMinFlow_Threshold + 40.0) THEN
            (* Approaching cavitation danger margin: Proactively open kickback choke *)
            bAntiCavitationActive     := TRUE;
            rInternalKickback_Cmd_Pct := ((rDynamicMinFlow_Threshold + 40.0 - rFilt_DischargeFlow_m3h) / 40.0) * 100.0;
        ELSIF rNetPositiveSuctionHeadMargin_m < 15.0 THEN
            (* Insufficient NPSH Margin: Cavitation inception override *)
            bAntiCavitationActive     := TRUE;
            rInternalKickback_Cmd_Pct := 65.0;
        ELSE
            (* Fully safe operating point: Kickback choke completely closed *)
            bAntiCavitationActive     := FALSE;
            rInternalKickback_Cmd_Pct := 0.0;
        END_IF;

        (* Track cumulative injected seawater volume [m3]: Q [m3/h] / 36000 cycles/hr *)
        rCumulativeInjected_m3 := rCumulativeInjected_m3 + (rFilt_DischargeFlow_m3h / 36000.0);

        (* State Transitions *)
        IF rFilt_DischargeFlow_m3h < rDynamicMinFlow_Threshold THEN
            iState := 40; (* Severe low-flow anti-cavitation surge *)
        ELSIF (iHealthy_PT_Count <= 1) OR (iHealthy_FT_Count <= 1) OR (rFilt_WindingTemp_DegC > 145.0) THEN
            iState := 50; (* Degraded thermal/sensor fallback *)
        END_IF;

    40: (* STATE_ANTI_CAVITATION_KICKBACK_SURGE: Immediate protective bypass dump *)
        bPumpSystemReady         := TRUE;
        bDegradedModeActive      := TRUE;
        bAntiCavitationActive    := TRUE;
        wPumpStatusWord          := 16#0040;
        wSubseaAlarmWord.7       := TRUE; (* Anti-cavitation surge active *)
        udiCavitationEventsTotal := udiCavitationEventsTotal + 1;

        (* Snap open anti-cavitation kickback choke valve to 100% within 1.2 seconds *)
        rInternalKickback_Cmd_Pct := 100.0;

        (* Decelerate VSD to minimum stable speed to shed thermal/cavitation energy *)
        IF rInternalSpeedDemand_rpm > 3400.0 THEN
            rInternalSpeedDemand_rpm := rInternalSpeedDemand_rpm - 35.0;
        END_IF;

        tonCavitationPersistence(IN := (rFilt_DischargeFlow_m3h >= (rDynamicMinFlow_Threshold + 60.0)) AND 
                                       (rNetPositiveSuctionHeadMargin_m >= 18.0),
                                 PT := T#10S);

        IF tonCavitationPersistence.Q THEN
            tonCavitationPersistence(IN := FALSE);
            wSubseaAlarmWord.7 := FALSE;
            iState             := 30; (* Re-enter Normal Steady-State MPC Injection *)
        END_IF;

    50: (* STATE_DEGRADED_TMR_THERMAL_BACKOFF: Restricted operational envelope *)
        bPumpSystemReady         := TRUE;
        bDegradedModeActive      := TRUE;
        wPumpStatusWord          := 16#0050;
        wSubseaAlarmWord.8       := TRUE; (* Degraded operations active *)

        (* Enforce conservative speed clamp and fixed 30% kickback flow to guarantee cooling *)
        IF rInternalSpeedDemand_rpm > 4200.0 THEN
            rInternalSpeedDemand_rpm := 4200.0;
        END_IF;

        IF rInternalKickback_Cmd_Pct < 30.0 THEN
            rInternalKickback_Cmd_Pct := 30.0;
        END_IF;

        (* Recovery back to full MPC if sensors restore and temperatures normalize *)
        IF (iHealthy_PT_Count >= 2) AND (iHealthy_FT_Count >= 2) AND 
           (rFilt_WindingTemp_DegC < 120.0) AND (rFilt_BearingTemp_DegC < 95.0) AND bAutoMpcEnable THEN
            wSubseaAlarmWord.8 := FALSE;
            iState             := 30;
        END_IF;

    90: (* STATE_CONTROLLED_RAMP_DOWN: Orderly deceleration avoiding hydraulic water hammer *)
        bPumpSystemReady         := FALSE;
        bDegradedModeActive      := FALSE;
        bAntiCavitationActive    := TRUE;
        wPumpStatusWord          := 16#0090;
        rInternalKickback_Cmd_Pct:= 100.0; (* Full bypass during shutdown *)

        IF rInternalSpeedDemand_rpm > 600.0 THEN
            rInternalSpeedDemand_rpm := rInternalSpeedDemand_rpm - 40.0;
        ELSE
            rInternalSpeedDemand_rpm := 0.0;
            iState                   := 0; (* Returned to cold seabed standby *)
        END_IF;

    99: (* STATE_SUBSEA_EMERGENCY_SHUTDOWN: Instantaneous de-energization *)
        bPumpSystemReady         := FALSE;
        bDegradedModeActive      := FALSE;
        bAntiCavitationActive    := TRUE;
        rInternalSpeedDemand_rpm := 0.0;
        rInternalKickback_Cmd_Pct:= 100.0;
        wPumpStatusWord          := 16#9999;

        IF (NOT bSubseaESD_Trip) AND bMasterPermissive AND bAcknowledgeFaults THEN
            wSubseaAlarmWord    := 16#0000;
            iState              := 0;
        END_IF;

END_CASE;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 6: ISA-18.2 SECONDARY SAFETY ALARM TREES & RATE-LIMITED ACTUATOR DRIVER
   --------------------------------------------------------------------------------------------------------------------- *)
(* Hydrodynamic thrust bearing high temperature trip threshold (115.0 deg C) *)
IF rFilt_BearingTemp_DegC > 115.0 THEN
    wSubseaAlarmWord.9 := TRUE; (* Thrust bearing overtemperature trip *)
    iState             := 99;   (* Trip subsea motor *)
ELSIF rFilt_BearingTemp_DegC > 105.0 THEN
    wSubseaAlarmWord.10 := TRUE; (* Thrust bearing high temp alarm *)
ELSE
    wSubseaAlarmWord.10 := FALSE;
END_IF;

(* Motor stator winding high temperature threshold (155.0 deg C Class F insulation limit) *)
IF rFilt_WindingTemp_DegC > 155.0 THEN
    wSubseaAlarmWord.11 := TRUE; (* Motor stator winding burnout trip *)
    iState              := 99;
ELSIF rFilt_WindingTemp_DegC > 140.0 THEN
    wSubseaAlarmWord.12 := TRUE; (* Stator high temperature warning *)
ELSE
    wSubseaAlarmWord.12 := FALSE;
END_IF;

(* Subsea Discharge Pipe Overpressure Protection (Design rating: 650.0 bar) *)
IF rFilt_DischargePress_bar > 635.0 THEN
    wSubseaAlarmWord.13 := TRUE; (* Casing overpressure protection *)
    rInternalKickback_Cmd_Pct := 100.0; (* Fast relief *)
    iState              := 90;   (* Force rapid ramp down *)
ELSE
    wSubseaAlarmWord.13 := FALSE;
END_IF;

(* Output Slew-Rate Limiting: VSD Ramp (Max 150 rpm/s) & Kickback Choke (Max 25%/s) *)
rVsdSpeedSetpoint_rpm := rInternalSpeedDemand_rpm;
rMinFlowValve_Cmd_Pct := rInternalKickback_Cmd_Pct;

END_FUNCTION_BLOCK
